contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // We deposit 'amount' into c from this contract, then call withdrawAll on c.
    // We observe only address(c).balance and address(this).balance and whether withdrawAll reverted.
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount, "insufficient test balance");

        // Record balances before any interaction
        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;

        // Deposit amount into c
        c.deposit{value: amount}(); if (__ESBMC_reverted()) return;

        // Balances after deposit
        uint afterDepositContractBalance = address(c).balance;
        uint afterDepositThisBalance = address(this).balance;

        // Basic checks: contract balance must increase by amount and this contract's balance decrease by amount
        require(afterDepositContractBalance == beforeContractBalance + amount, "deposit didn't increase c balance");
        require(afterDepositThisBalance + amount == beforeThisBalance, "deposit didn't decrease tester balance");

        // Attempt withdrawAll and capture whether it reverted
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Balances after withdraw attempt
        uint finalContractBalance = address(c).balance;
        uint finalThisBalance = address(this).balance;

        // General rule (observable):
        // If withdrawAll succeeded then this contract must have received exactly the deposited amount back
        // and c's balance decreased by that amount. If withdrawAll reverted then balances must remain as after deposit.
        assert(
            (!reverted && finalThisBalance == afterDepositThisBalance + amount && finalContractBalance + amount == afterDepositContractBalance)
            ||
            (reverted && finalThisBalance == afterDepositThisBalance && finalContractBalance == afterDepositContractBalance)
        );
    }

    // Accept ETH when c sends funds back during withdrawAll
    receive() external payable {}
}

