// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ReentrancyDAO c;

    function setUp() public {
        c = new ReentrancyDAO();
    }

    function _run(uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        uint beforeContractBalance = address(c).balance;
        uint beforeThisBalance = address(this).balance;
        try c.deposit{value: amount}() {} catch { return; }
        uint afterDepositContractBalance = address(c).balance;
        uint afterDepositThisBalance = address(this).balance;
        vm.assume(afterDepositContractBalance == beforeContractBalance + amount);
        vm.assume(afterDepositThisBalance + amount == beforeThisBalance);
        bool reverted;
        try c.withdrawAll() {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint finalContractBalance = address(c).balance;
        uint finalThisBalance = address(this).balance;
        assertTrue((!reverted && finalThisBalance == afterDepositThisBalance + amount && finalContractBalance + amount == afterDepositContractBalance)
            ||
            (reverted && finalThisBalance == afterDepositThisBalance && finalContractBalance == afterDepositContractBalance));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
